ENG_raise_the_home_guard_in_state = {

	icon = GFX_decision_generic_protection

	allowed = {
		original_tag = ENG
	} 

	priority = 80

	visible = {
		is_subject = no
		has_civil_war = no
		has_country_flag = ENG_home_guard_established_flag
	}

	available = {
		has_war = yes
		any_owned_state = {
			is_core_of = ROOT
			#is_in_home_area = yes 	
			NOT = {
				is_controlled_by = ROOT
			}
		}
		NOT = {
			has_country_flag = ENG_raising_militia_flag
		}
	}

	state_target = yes

	on_map_mode = map_and_decisions_view

	target_array = ROOT.core_states

	target_trigger = {
		FROM = {
			OR = {
				state = 126
				state = 128
				state = 130
				state = 132
				state = 121
				state = 133
			}
			NOT = {
				has_state_flag = {
					flag = ENG_raised_home_guard_here_already_flag
				}	
			}
			is_controlled_by = ROOT
		}			
	}

	cost = 25

	fire_only_once = yes

	days_remove = 7
